const dicts = { en, zh };
let current = 'en';

export function detectLang(saved) {
  if (saved === 'en' || saved === 'zh') return saved;
  return (navigator.language || '').toLowerCase().startsWith('zh') ? 'zh' : 'en';
}
export function setLang(l) { current = dicts[l] ? l : 'en'; document.documentElement.lang = current === 'zh' ? 'zh-CN' : 'en'; }
export function lang() { return current; }
export function t(key, vars) {
  let s = dicts[current][key] ?? en[key] ?? key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? ''));
  return s;
}
export function has(key) { return key in en; }

export function relTime(ms) {
  if (!ms) return '';
  const diff = (Date.now() - ms) / 1000;
  const rtf = new Intl.RelativeTimeFormat(current === 'zh' ? 'zh-CN' : 'en', { numeric: 'auto' });
  const steps = [[60, 'second'], [60, 'minute'], [24, 'hour'], [30, 'day'], [12, 'month'], [Infinity, 'year']];
  let v = -diff;
  for (const [n, unit] of steps) {
    if (Math.abs(v) < n) return rtf.format(Math.round(v), unit);
    v /= n;
  }
  return '';
}
